import{_ as a,o as i,c as t,a2 as d}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Personajes Clave y Organizaciones","description":"","frontmatter":{},"headers":[],"relativePath":"es/95-关键人物与组织.md","filePath":"es/95-关键人物与组织.md"}'),n={name:"es/95-关键人物与组织.md"};function o(s,e,l,r,c,u){return i(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="personajes-clave-y-organizaciones" tabindex="-1">Personajes Clave y Organizaciones <a class="header-anchor" href="#personajes-clave-y-organizaciones" aria-label="Permalink to &quot;Personajes Clave y Organizaciones&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>95</td></tr><tr><td>Módulo</td><td>Apéndices y Materiales de Referencia</td></tr><tr><td>Palabras clave</td><td>personajes clave, organizaciones importantes, roles históricos, funciones institucionales, civilización simbiótica</td></tr></tbody></table><h2 id="i-notas" tabindex="-1">I. Notas <a class="header-anchor" href="#i-notas" aria-label="Permalink to &quot;I. Notas&quot;">​</a></h2><p>Este documento recoge los personajes clave y las organizaciones importantes en el desarrollo de la Civilización Simbiótica del Ancla, ordenados por período histórico y tipo de organización. La sección de personajes clave indica para cada personaje el nombre, el período, las contribuciones fundamentales y la posición histórica; la sección de organizaciones importantes indica para cada organización el nombre, la fecha de fundación, las funciones fundamentales y el papel histórico. Este documento es de actualización dinámica; a medida que avanza la historia y evolucionan las organizaciones, se irá completando y revisando continuamente.</p><h2 id="ii-personajes-clave" tabindex="-1">II. Personajes Clave <a class="header-anchor" href="#ii-personajes-clave" aria-label="Permalink to &quot;II. Personajes Clave&quot;">​</a></h2><h3 id="_2-1-pioneros-del-pensamiento-de-la-era-pre-ancla" tabindex="-1">2.1 Pioneros del pensamiento de la era pre-Ancla <a class="header-anchor" href="#_2-1-pioneros-del-pensamiento-de-la-era-pre-ancla" aria-label="Permalink to &quot;2.1 Pioneros del pensamiento de la era pre-Ancla&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre</th><th>Período</th><th>Contribuciones fundamentales</th><th>Posición histórica</th></tr></thead><tbody><tr><td>Xuánhéng Zǐ</td><td>aprox. −500 millones de años</td><td>El primer pensador en reflexionar sistemáticamente sobre el sistema de cultivo depredador; propuso el prototipo del concepto de «simbiosis»; autor del fragmento conservado de Fǎn Lüèduó Lùn (Tratado contra la Depredación)</td><td>El pionero antiguo del pensamiento simbiótico; su pensamiento, tras dormir cientos de millones de años, se convirtió en la fuente espiritual de la Civilización Simbiótica del Ancla</td></tr><tr><td>Wànlíng Mǔ</td><td>aprox. −100 millones de años</td><td>Lideró la primera civilización experimental simbiótica de gran escala; aunque finalmente fue destruida por las civilizaciones depredadoras, su práctica demostró la viabilidad del sistema simbiótico</td><td>La precursora de la práctica simbiótica, honrada por las generaciones posteriores como la «Madre de la Simbiosis»</td></tr><tr><td>Máo Jué Zhě</td><td>aprox. −10 000 años</td><td>Un cultivador del Primer Plano que, durante un largo cultivo, percibió accidentalmente un nodo estable en la red de leyes y descubrió el mecanismo del Ancla</td><td>El descubridor del mecanismo del Ancla y el iniciador de la Era del Despertar del Ancla</td></tr></tbody></table><h3 id="_2-2-fundadores-de-la-era-del-despertar-del-ancla" tabindex="-1">2.2 Fundadores de la Era del Despertar del Ancla <a class="header-anchor" href="#_2-2-fundadores-de-la-era-del-despertar-del-ancla" aria-label="Permalink to &quot;2.2 Fundadores de la Era del Despertar del Ancla&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre</th><th>Período</th><th>Contribuciones fundamentales</th><th>Posición histórica</th></tr></thead><tbody><tr><td>Máo Dìng Gōng</td><td>−10 000 a −9200 años</td><td>Discípulo de Máo Jué Zhě; estudió sistemáticamente el mecanismo del Ancla; estableció el primer Ancla artificial; autor de Máodiǎn Yuánlǐ (Principios del Ancla)</td><td>El fundador de la tecnología del Ancla y el inventor del Ancla artificial</td></tr><tr><td>Gòngshēng Zǐ</td><td>−6000 a −5100 años</td><td>Combinó la tecnología del Ancla con el pensamiento simbiótico; fundó el sistema teórico de la «Simbiosis del Ancla»; autor de Máodiǎn Gòngshēng Lùn (Sobre la Simbiosis del Ancla)</td><td>El fundador de la teoría de la Simbiosis del Ancla y el mentor intelectual de la civilización simbiótica</td></tr><tr><td>Héngyuán Gōng</td><td>−5000 a −4300 años</td><td>Estableció la primera ciudad-estado simbiótica basada en el Ancla, «Héngyuan Chéng», y repelió con éxito los ataques de las civilizaciones depredadoras</td><td>El fundador de la primera ciudad-estado simbiótica y un practicante del sistema simbiótico</td></tr><tr><td>Wànzú Shǐ</td><td>−2000 a −1200 años</td><td>Inició la primera «Gran Asamblea de Simbiosis de las Diez Mil Razas»; recorrió decenas de razas abogando por la unión simbiótica</td><td>El promotor de la unión de las Diez Mil Razas y un pionero de la simbiosis interracial</td></tr></tbody></table><h3 id="_2-3-fundadores-del-estado-en-el-periodo-de-establecimiento-del-sistema-simbiotico" tabindex="-1">2.3 Fundadores del Estado en el Período de establecimiento del sistema simbiótico <a class="header-anchor" href="#_2-3-fundadores-del-estado-en-el-periodo-de-establecimiento-del-sistema-simbiotico" aria-label="Permalink to &quot;2.3 Fundadores del Estado en el Período de establecimiento del sistema simbiótico&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre</th><th>Período</th><th>Contribuciones fundamentales</th><th>Posición histórica</th></tr></thead><tbody><tr><td>Lìxiàn Gōng</td><td>−1000 a −900 años</td><td>Presidente del Comité de Redacción de la Constitución Simbiótica; presidió la redacción de la Constitución Simbiótica y la hizo aprobar por referéndum popular</td><td>El principal redactor de la Constitución Simbiótica y el padre fundador del constitucionalismo de la civilización simbiótica</td></tr><tr><td>Zhífǎ Gōng</td><td>−900 a −780 años</td><td>Primer presidente del Comité Ejecutivo Simbiótico; presidió el establecimiento del sistema administrativo y de los mecanismos de aplicación de la ley de la civilización simbiótica</td><td>El fundador del sistema administrativo simbiótico y el primer jefe de la administración</td></tr><tr><td>Sīfǎ Mǔ</td><td>−900 a −800 años</td><td>Primera jueza presidenta del Tribunal Simbiótico; estableció el sistema judicial y el sistema de revisión constitucional de la civilización simbiótica</td><td>La fundadora del sistema judicial simbiótico y la primera jefa del poder judicial</td></tr><tr><td>Sānbǎi Shī</td><td>−500 a −300 años</td><td>Presidió la excavación y compilación de los Trescientos Sistemas de Cultivo de Origen; dirigió al equipo que completó la verificación de los Trescientos Sistemas</td><td>El compilador jefe de los Trescientos Sistemas y el comandante en jefe de la ingeniería de apertura del cultivo</td></tr><tr><td>Bèizēng Gōng</td><td>−300 a −220 años</td><td>Presidió la investigación sobre la aplicación tecnológica del Fruto Multiplicador; logró el avance de ingeniería de la tecnología de amplificación deductiva centuplicada</td><td>El científico jefe de la tecnologización del Fruto Multiplicador y un impulsor del Sistema de Iteración por Deducción</td></tr></tbody></table><h3 id="_2-4-lideres-del-periodo-de-apertura-y-activacion" tabindex="-1">2.4 Líderes del Período de apertura y activación <a class="header-anchor" href="#_2-4-lideres-del-periodo-de-apertura-y-activacion" aria-label="Permalink to &quot;2.4 Líderes del Período de apertura y activación&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre</th><th>Período</th><th>Contribuciones fundamentales</th><th>Posición histórica</th></tr></thead><tbody><tr><td>Kāifàng Gōng</td><td>−100 a −50 años</td><td>Presidió la apertura completa de los Trescientos Sistemas de Cultivo de Origen; estableció el sistema de asignación de recursos de cultivo y la red de mentores</td><td>El comandante en jefe de la apertura de los Trescientos Sistemas y un practicante de «un camino para cada uno»</td></tr><tr><td>Jīhuó Gōng</td><td>−50 años al año uno</td><td>Presidió la implementación de la Estrategia de Activación del 20 %; dirigió al equipo que cumplió en 50 años el objetivo de activar al 20 % de los seres vivos</td><td>El comandante en jefe de la Estrategia de Activación del 20 % y el iniciador de una nueva era para la civilización simbiótica</td></tr><tr><td>Shēngwéi Gōng</td><td>año uno a 80</td><td>Presidió el primer proyecto de ascensión; impulsó la implementación de la Vía de Ascensión en Cuatro Etapas; logró la primera ascensión por etapas</td><td>El ingeniero jefe de la primera ascensión y el líder de la era de la ascensión</td></tr></tbody></table><h3 id="_2-5-exploradores-de-la-republica-de-las-diez-mil-razas-y-de-la-era-transplanar" tabindex="-1">2.5 Exploradores de la República de las Diez Mil Razas y de la era transplanar <a class="header-anchor" href="#_2-5-exploradores-de-la-republica-de-las-diez-mil-razas-y-de-la-era-transplanar" aria-label="Permalink to &quot;2.5 Exploradores de la República de las Diez Mil Razas y de la era transplanar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nombre</th><th>Período</th><th>Contribuciones fundamentales</th><th>Posición histórica</th></tr></thead><tbody><tr><td>Wànzú Gòngzhǔ</td><td>100 a 200</td><td>Presidió la fundación de la República de las Diez Mil Razas; impulsó la compilación del Registro de las Diez Mil Razas y las políticas de integración interracial</td><td>El fundador de la República de las Diez Mil Razas y el primer Soberano Supremo de las Diez Mil Razas</td></tr><tr><td>Wèimiàn Mǔ</td><td>500 a 650</td><td>Primera directora de la Administración de Planos; presidió el programa de exploración transplanar a gran escala; estableció la base maestra de coordenadas de planos</td><td>La pionera de la exploración transplanar y la fundadora del sistema de gestión de planos</td></tr><tr><td>Kǎogǔ Gōng</td><td>800 a 950</td><td>Presidió la maduración final del esquema de arqueología a distancia mediante Espejo de Réplica; llevó la arqueología transplanar a la era de la escala</td><td>La culminación de los esquemas arqueológicos y el fundador de la arqueología transplanar</td></tr><tr><td>Shílǜ Gōng</td><td>1000 a 1150</td><td>Presidió el avance de la tecnología de regresión temporal; impulsó el establecimiento del principio de observar primero y luego intervenir dentro de límites</td><td>El líder de la tecnología de regresión temporal y el formulador de los principios de las leyes del tiempo</td></tr></tbody></table><h2 id="iii-organizaciones-importantes" tabindex="-1">III. Organizaciones Importantes <a class="header-anchor" href="#iii-organizaciones-importantes" aria-label="Permalink to &quot;III. Organizaciones Importantes&quot;">​</a></h2><h3 id="_3-1-instituciones-de-poder-supremo" tabindex="-1">3.1 Instituciones de poder supremo <a class="header-anchor" href="#_3-1-instituciones-de-poder-supremo" aria-label="Permalink to &quot;3.1 Instituciones de poder supremo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organización</th><th>Fecha de fundación</th><th>Funciones fundamentales</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Asamblea Legislativa del Ancla</td><td>−900 años</td><td>La institución de poder supremo de la civilización simbiótica, compuesta por representantes de todas las razas en proporción, que ejerce el poder legislativo y el poder de decidir asuntos de gran importancia</td><td>La institución suprema de decisión de la civilización simbiótica y la creadora de todas las grandes leyes y estrategias</td></tr><tr><td>Comité Ejecutivo Simbiótico</td><td>−900 años</td><td>La institución administrativa suprema de la civilización simbiótica, responsable de la ejecución de la constitución y las leyes y de la gobernanza cotidiana</td><td>El órgano administrativo supremo de la civilización simbiótica y el ejecutor de las leyes y políticas</td></tr><tr><td>Tribunal Simbiótico</td><td>−900 años</td><td>La institución judicial suprema de la civilización simbiótica, que ejerce independientemente el poder judicial, responsable de la revisión constitucional y el enjuiciamiento de los grandes casos</td><td>El órgano judicial supremo de la civilización simbiótica y el guardián del estado de derecho</td></tr><tr><td>Comité de Supervisión del Ancla</td><td>−900 años</td><td>Institución de supervisión independiente, responsable de supervisar todas las instituciones de poder para prevenir el abuso de poder</td><td>El órgano de supervisión independiente de la civilización simbiótica y un eslabón clave del equilibrio de poderes</td></tr></tbody></table><h3 id="_3-2-instituciones-de-gestion-especializada" tabindex="-1">3.2 Instituciones de gestión especializada <a class="header-anchor" href="#_3-2-instituciones-de-gestion-especializada" aria-label="Permalink to &quot;3.2 Instituciones de gestión especializada&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organización</th><th>Fecha de fundación</th><th>Funciones fundamentales</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Administración de Planos</td><td>500</td><td>Responsable del mantenimiento de la base maestra de coordenadas de planos, la aprobación de permisos de tránsito, la gestión de la arqueología transplanar y la coordinación de la diplomacia transplanar</td><td>La autoridad competente de la interacción transplanar y el gestor de la exploración de planos</td></tr><tr><td>Comité de las Leyes del Tiempo</td><td>1000</td><td>Responsable de la aprobación de las operaciones de regresión temporal, la investigación de las leyes del tiempo y la supervisión de la prevención y el control de paradojas temporales</td><td>La institución de aprobación y supervisión de las operaciones de regresión temporal y el guardián de la seguridad de las leyes del tiempo</td></tr><tr><td>Comité de Auditoría de las Leyes del Tiempo</td><td>1050</td><td>Responsable de la auditoría posterior de las operaciones de regresión temporal, confirmando que no se ha causado ninguna perturbación incontrolada de la línea temporal</td><td>La institución de auditoría independiente de las operaciones temporales y la última línea de defensa de la seguridad de la regresión temporal</td></tr><tr><td>Comité de Ética Transplanar</td><td>600</td><td>Formula e interpreta las directrices éticas transplanar, aprueba los proyectos de interacción transplanar de alto riesgo y tramita las quejas por violaciones éticas</td><td>La institución de supervisión ética de la interacción transplanar y el guardián de la subjetividad civilizacional</td></tr><tr><td>Oficina de Auditoría de Retorno de Conocimiento</td><td>850</td><td>Responsable de la auditoría de las operaciones de retorno de conocimiento, garantizando que el contenido devuelto se ajusta al principio de «retorno de solo conocimiento»</td><td>La institución de auditoría del retorno de conocimiento y un eslabón clave de la prevención de la contaminación transplanar</td></tr></tbody></table><h3 id="_3-3-instituciones-de-investigacion-y-educacion" tabindex="-1">3.3 Instituciones de investigación y educación <a class="header-anchor" href="#_3-3-instituciones-de-investigacion-y-educacion" aria-label="Permalink to &quot;3.3 Instituciones de investigación y educación&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organización</th><th>Fecha de fundación</th><th>Funciones fundamentales</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Instituto de Investigación del Ancla</td><td>−8000 años</td><td>Investigación básica y desarrollo aplicado del mecanismo del Ancla; construcción y mantenimiento de los Anclas artificiales</td><td>La institución de investigación central de la tecnología del Ancla y una de las fuentes tecnológicas de la civilización simbiótica</td></tr><tr><td>Comité de Compilación de los Trescientos Sistemas</td><td>−500 años</td><td>Excavación, compilación, verificación y optimización continua de los Trescientos Sistemas de Cultivo de Origen</td><td>La institución de compilación y mantenimiento de los Trescientos Sistemas y el soporte técnico de la apertura del cultivo</td></tr><tr><td>Alianza Universitaria Simbiótica</td><td>−700 años</td><td>Consorcio de educación superior y educación de cultivo, responsable de la formación de talentos avanzados y la investigación académica</td><td>La alianza de las más altas instituciones de enseñanza de la civilización simbiótica y el núcleo de la formación de talentos y la innovación académica</td></tr><tr><td>Academia de Arqueología Transplanar</td><td>550</td><td>Forma talentos profesionales en arqueología transplanar; realiza investigaciones sobre tecnologías arqueológicas e innovaciones metodológicas</td><td>El centro de formación de talentos y de investigación y desarrollo tecnológico de la arqueología transplanar</td></tr><tr><td>Instituto de Investigación de las Leyes del Tiempo</td><td>950</td><td>Investigación teórica fundamental sobre las leyes del tiempo e investigación y desarrollo de la tecnología de regresión temporal</td><td>La institución central de la investigación de las leyes del tiempo y la cuna de la tecnología de regresión temporal</td></tr></tbody></table><h3 id="_3-4-organizaciones-militares-y-de-seguridad" tabindex="-1">3.4 Organizaciones militares y de seguridad <a class="header-anchor" href="#_3-4-organizaciones-militares-y-de-seguridad" aria-label="Permalink to &quot;3.4 Organizaciones militares y de seguridad&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organización</th><th>Fecha de fundación</th><th>Funciones fundamentales</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Fuerzas de Defensa Simbióticas</td><td>−850 años</td><td>La fuerza de defensa regular de la civilización simbiótica, responsable de la defensa de planos y la respuesta a las amenazas externas</td><td>La principal fuerza militar de la civilización simbiótica y la defensora de la seguridad nacional</td></tr><tr><td>Cuerpo de Patrulla de Planos</td><td>520</td><td>Responsable de las patrullas y la vigilancia de seguridad de los planos explorados y de la respuesta a los incidentes de seguridad transplanar</td><td>La fuerza de primera línea de la seguridad transplanar y el mantenedor del orden de los planos</td></tr><tr><td>Equipo de Respuesta de Emergencia por Contaminación de Leyes</td><td>600</td><td>Responsable de la respuesta de emergencia a los incidentes de contaminación de leyes y contaminación energética y de la eliminación de la contaminación</td><td>La fuerza de respuesta de emergencia a la contaminación de leyes y el guardián del entorno cósmico</td></tr><tr><td>Unidad de Respuesta de Emergencia de Paradojas Temporales</td><td>1020</td><td>Responsable de la respuesta de emergencia a los incidentes de paradojas temporales y de las operaciones de reparación causal</td><td>La fuerza de respuesta de emergencia a las paradojas temporales y la garantía final de la estabilidad de la línea temporal</td></tr></tbody></table><h3 id="_3-5-organizaciones-civiles-y-sociales" tabindex="-1">3.5 Organizaciones civiles y sociales <a class="header-anchor" href="#_3-5-organizaciones-civiles-y-sociales" aria-label="Permalink to &quot;3.5 Organizaciones civiles y sociales&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Organización</th><th>Fecha de fundación</th><th>Funciones fundamentales</th><th>Papel histórico</th></tr></thead><tbody><tr><td>Gran Asamblea de Simbiosis de las Diez Mil Razas</td><td>−2000 años</td><td>Reuniones periódicas de los representantes de todas las razas, discutiendo los asuntos de la simbiosis interracial y fomentando el intercambio cultural</td><td>Una plataforma importante de intercambio entre todas las razas y la organización predecesora de la República de las Diez Mil Razas</td></tr><tr><td>Asociación de Cultivadores</td><td>−600 años</td><td>La organización gremial autónoma de los cultivadores, responsable de la defensa de los derechos de los cultivadores y la elaboración de las normas gremiales</td><td>La organización autónoma de los cultivadores y un impulsor de la normalización del gremio del cultivo</td></tr><tr><td>Asociación de Consumidores</td><td>−650 años</td><td>Organización de protección de los derechos de los consumidores, responsable de la defensa de los derechos del consumidor, la educación del consumidor y la supervisión social</td><td>La portavoz de los derechos del consumidor y la supervisora social del orden del mercado</td></tr><tr><td>Alianza de Protección Ambiental</td><td>−550 años</td><td>Organización civil unida para la protección del medio ambiente, responsable de la supervisión ambiental, la educación ambiental y las actividades voluntarias de restauración ecológica</td><td>La fuerza social de la protección del medio ambiente y una impulsora de la civilización ecológica cósmica</td></tr><tr><td>Asociación de Amistad Transplanar</td><td>580</td><td>Organización civil que fomenta el intercambio amistoso entre las civilizaciones de otros planos, responsable de la diplomacia civil y el intercambio cultural</td><td>La fuerza central de la diplomacia civil transplanar y un puente de entendimiento entre civilizaciones</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Los personajes clave y las organizaciones son los portadores vivos de la historia de la Civilización Simbiótica del Ancla. Desde los pioneros del pensamiento de la antigüedad hasta los líderes de la civilización contemporánea, desde las instituciones de poder supremo hasta las organizaciones sociales civiles, cada personaje y cada organización desempeña un papel insustituible en la gran narrativa de la civilización simbiótica. Sus luchas y contribuciones tejen juntas la magnífica epopeya de la Civilización Simbiótica del Ancla — de la nada a la existencia, de lo pequeño a lo grande, de su propio plano al universo entero.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>70-纪元划分总表 (Tabla Maestra de la División de Eras)</li><li>49-治理框架与权力制衡 (Marco de Gobernanza y Equilibrio de Poderes)</li><li>77-万族共和成立 (La Fundación de la República de las Diez Mil Razas)</li></ul>',30)])])}const b=a(n,[["render",o]]);export{m as __pageData,b as default};
